   784	func (l *base) scanPorts() (err error) {
   785		l.log.Info("Scanning listen port...")
   786		dest := l.detectScanDest()
   787		open, err := l.execPortsScan(dest)
   788		if err != nil {
   789			return err
   790		}
   791		l.updatePortStatus(open)
   792	
   793		return nil
   794	}
