   796	func (l *base) detectScanDest() map[string][]string {
   797		scanIPPortsMap := map[string][]string{}
   798	
   799		for _, p := range l.osPackages.Packages {
   800			if p.AffectedProcs == nil {
   801				continue
   802			}
   803			for _, proc := range p.AffectedProcs {
   804				if proc.ListenPortStats == nil {
   805					continue
   806				}
   807				for _, port := range proc.ListenPortStats {
   808					scanIPPortsMap[port.BindAddress] = append(scanIPPortsMap[port.BindAddress], port.Port)
   809				}
   810			}
   811		}
   812	
   813		scanDestIPPorts := map[string][]string{}
   814		for addr, ports := range scanIPPortsMap {
   815			if addr == "*" {
   816				for _, addr := range l.ServerInfo.IPv4Addrs {
   817					scanDestIPPorts[addr] = append(scanDestIPPorts[addr], ports...)
   818				}
   819			} else {
   820				scanDestIPPorts[addr] = append(scanDestIPPorts[addr], ports...)
   821			}
   822		}
   823	
   824		uniqScanDestIPPorts := map[string][]string{}
   825		for i, scanDest := range scanDestIPPorts {
   826			m := map[string]bool{}
   827			for _, e := range scanDest {
   828				if !m[e] {
   829					m[e] = true
   830					uniqScanDestIPPorts[i] = append(uniqScanDestIPPorts[i], e)
   831				}
   832			}
   833		}
   834	
   835		return uniqScanDestIPPorts
   836	}
   837	
   838	func (l *base) execPortsScan(scanDestIPPorts map[string][]string) ([]string, error) {
   839		listenIPPorts := []string{}
   840	
   841		for ip, ports := range scanDestIPPorts {
   842			if !isLocalExec(l.ServerInfo.Port, l.ServerInfo.Host) && net.ParseIP(ip).IsLoopback() {
   843				continue
   844			}
   845			for _, port := range ports {
   846				scanDest := ip + ":" + port
   847				conn, err := net.DialTimeout("tcp", scanDest, time.Duration(1)*time.Second)
   848				if err != nil {
   849					continue
   850				}
   851				conn.Close()
   852				listenIPPorts = append(listenIPPorts, scanDest)
   853			}
   854		}
   855	
   856		return listenIPPorts, nil
   857	}
