   859	func (l *base) updatePortStatus(listenIPPorts []string) {
   860		for name, p := range l.osPackages.Packages {
   861			if p.AffectedProcs == nil {
   862				continue
   863			}
   864			for i, proc := range p.AffectedProcs {
   865				if proc.ListenPortStats == nil {
   866					continue
   867				}
   868				for j, port := range proc.ListenPortStats {
   869					l.osPackages.Packages[name].AffectedProcs[i].ListenPortStats[j].PortReachableTo = l.findPortTestSuccessOn(listenIPPorts, port)
   870				}
   871			}
   872		}
   873	}
   874	
   875	func (l *base) findPortTestSuccessOn(listenIPPorts []string, searchListenPort models.PortStat) []string {
   876		addrs := []string{}
   877	
   878		for _, ipPort := range listenIPPorts {
   879			ipPort, err := models.NewPortStat(ipPort)
   880			if err != nil {
   881				l.log.Warnf("Failed to find: %+v", err)
   882				continue
   883			}
   884			if searchListenPort.BindAddress == "*" {
   885				if searchListenPort.Port == ipPort.Port {
   886					addrs = append(addrs, ipPort.BindAddress)
   887				}
   888			} else if searchListenPort.BindAddress == ipPort.BindAddress && searchListenPort.Port == ipPort.Port {
   889				addrs = append(addrs, ipPort.BindAddress)
   890			}
   891		}
   892	
   893		return addrs
   894	}
